entries[192743] = { ["name"] = "Wild Bushfruit", ["text"] = "Quest Item\nUse: Feed a Wild Bushfruit to a hungry mudstomper within 20 yards. (3 Sec Cooldown)\n\"A cool burst of mint and the perfect amount of crunch.\"" }
entries[192744] = { ["name"] = "Rymek's Gift", ["text"] = "Quest Item\n\"Dynamic, but very cold, gemstones.\"" }
entries[192745] = { ["name"] = "The Titanic Comedy", ["text"] = "Quest Item\n\"A satirical tour of the cosmos, from the Emerald Dream to the Shadowlands, led by the titan watcher Dantyr. Neither titans nor aspects are spared the author's ire, all having their perceived sins on full display.\"" }
entries[192746] = { ["name"] = "Curio of Yore", ["text"] = "\"An unrecognizable vestige of a time long past.\"\nSell Price:" }
entries[192747] = { ["name"] = "Broken Branch", ["text"] = "Sell Price:" }
entries[192749] = { ["name"] = "Chrono Crystal", ["text"] = "Quest Item\nUnique\nUse: Attunes the target to their proper timeline." }
entries[192750] = { ["name"] = "Black Iron Javelin", ["text"] = "Quest Item\nUnique\nUse: Throw at a Primordial Trueblood in order to pull it out of the sky. (5 Sec Cooldown)" }
entries[192751] = { ["name"] = "Stormtouched Bruffalon", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\"Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\"" }
entries[192752] = { ["name"] = "Staff Headpiece", ["text"] = "Quest Item\n\"The detached focus from a broken Timewalker staff.\"" }
entries[192753] = { ["name"] = "The Scales of Wrath", ["text"] = "Quest Item\n\"A savagely poignant rebuttal of the order imposed by the aspects and their titan allies. Told from the point of view of a protodrake who would eventually feel forced to rebel after being pushed to the edges of draconic society.\"" }
entries[192754] = { ["name"] = "Dracuixote", ["text"] = "Quest Item\n\"The story of an ancient green dragon who could no longer tell his dreams from the waking world. Accompanied by a long suffering dragonspawn, Dracuixote embarks on a fanciful quest to restore an imagined golden age.\"" }
entries[192755] = { ["name"] = "The Lord of the Wings", ["text"] = "Quest Item\n\"A band of hardened drakonid and plucky whelps come together to destroy an artifact of terrible power that can only be undone in the forges of the mad aspect who created it.\"" }
entries[192756] = { ["name"] = "The Red and the Black Flights", ["text"] = "Quest Item\n\"A low-born black drake fails to reconcile his militaristic heritage with his respect for intelligence and wit, eventually falling to despair over unrequited love and the materialism rampant among dragonkind.\"" }
entries[192757] = { ["name"] = "Pride and Protodrakes", ["text"] = "Quest Item\n\"The quintessential love story. Set in a time before the aspects, an up-and-coming young protodrake runs afoul of a standoffish elder. Their animosity turns to appreciation and, eventually, love as they come to understand each other.\"" }
entries[192758] = { ["name"] = "Coil of Heavy Rope", ["text"] = "Quest Item\n\"Heavy as defined by dragonkin. You could likely haul boulders with a single coil.\"" }
entries[192759] = { ["name"] = "Magmasworn Spear", ["text"] = "Quest Item\n\"Point towards enemy and strongly apply jabbing motion.\"" }
entries[192761] = { ["name"] = "Tamed Skitterfly", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 25 with the Dragonscale Expedition.\n\n\"It didn't take long for Granpap Whiskers to tame the skitterflies around the Dragonscale Basecamp and set them to helping move Expedition personnel and cargo.\"\nFaction:\nDragonscale Expedition\nRenown:\n25\nVendor:\nGranpap Whiskers\nLocation:\nDragonscale Basecamp" }
entries[192762] = { ["name"] = "Azure Skitterfly", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 25 with the Dragonscale Expedition.\n\n\"Once Granpap Whiskers finally taught them how to take riders, the azure skitterflies proved to bond closely and loyally to their riders.\"\nFaction:\nDragonscale Expedition\nRenown:\n25\nVendor:\nGranpap Whiskers\nLocation:\nDragonscale Basecamp\nCost:\n5\n20\n750" }
entries[192764] = { ["name"] = "Verdant Skitterfly", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Verdant skitterflies are the perfect mount for the scouts of the Dragonscale Expedition scouts, as they are fast and blend into the foliage of the Dragon Isles.\"\nFaction:\nDragonscale Expedition\nRenown:\n25\nTreasure:\nExpedition Scout's Pack" }
entries[192765] = { ["name"] = "Bestowed Sandskimmer", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"A gift from Granpap Whiskers, these capricious skitterflies help the Timewalkers clean up present (and future) sand-related temporal calamities.\"\nAchievement:\nClosing Time\nCategory:\nExploration" }
entries[192766] = { ["name"] = "Amber Skitterfly", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"A gift from Granpap Whiskers to the Trading Post, amber skitterflies are remarkably docile.\"\nTrading Post" }
entries[192767] = { ["name"] = "Bag of Ore", ["text"] = "Quest Item" }
entries[192768] = { ["name"] = "Titan Disc", ["text"] = "Quest Item\n\"Engraved with intricate symbols, the Titan Disc emits a faint glow.\"" }
entries[192769] = { ["name"] = "Cracked Spear", ["text"] = "\"This weapon is no longer servicable for combat.\"\nSell Price:" }
entries[192772] = { ["name"] = "Ancient Salamanther", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Due to their preference for dark caves and murky waters, sightings of this unique breed of salamanther are so rare that many researchers thought they had gone extinct.\"\nDrop:\nThe Forbidden Reach" }
entries[192774] = { ["name"] = "Coralscale Salamanther", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"As Raszageth's storms abated, this aquatic breed of salamanther was among the many wonders to settle among the shores in their wake.\"\nAchievement:\nInto the Storm\nCategory:\nExploration" }
entries[192775] = { ["name"] = "Stormhide Salamanther", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Sometimes when storm energies infuse a creature, it simply... becomes larger and more placid. Few salamanthers are willing to be ridden, but these children of the storm are a notable exception.\"\nVendor:\nMythressa\nCost:\n2000" }
entries[192776] = { ["name"] = "Dormant Embercone", ["text"] = "Quest Item\n\"This seed is warm to the touch, containing enough energy to grow to dizzying heights.\"" }
entries[192777] = { ["name"] = "Magmashell", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Who's a good little new-forged snail made entirely of elemental lava? You are! Yes, you!\"\nItem:\nEmpty Magma Shell\nZone:\nThe Waking Shores" }
entries[192779] = { ["name"] = "Seething Slug", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Drawn forth from its abyss by the rage of the Zaqali.\"\nTreasure:\nSeething Cache\nZone:\nZaralek Cavern" }
entries[192783] = { ["name"] = "Nokhud Vanguard Orders", ["text"] = "Quest Item\n\"Taken from the body of a Nokhud assassin.\"\n<Right Click to Read>" }
entries[192784] = { ["name"] = "Shellack", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Fed by victory and hardened by glory, this snail is nothing less than a tribute to mastery.\"\nAchievement:\nGlory of the Dragonflight Hero" }
entries[192785] = { ["name"] = "Gooey Snailemental", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Formed from the leftover elemental energies of the Primal Storms, this magical mollusk is faster than it appears.\"\nDrop:\nThe Forbidden Reach" }
entries[192786] = { ["name"] = "Slumbering Worldsnail Shell", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"For the Worldbreakers, a portable footstool. For you, a hardy mount.\"\nVendor:\nDealer Vexil\nZone:\nThe Waking Shores\nCost:\n1000" }
entries[192788] = { ["name"] = "Bestowed Trawling Mammoth", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"A gift from Scout Tomul, so that the feasts of Iskaara will always have enough fish to feed those in need.\"\nAchievement:\nArmy of the Fed\nCategory:\nExploration" }
entries[192790] = { ["name"] = "Mossy Mammoth", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Preserved for thousands of years in stone, bronze magic has nearly aged this mammoth back into a fossil.\"\nDrop:\nZskera Vaults" }
entries[192791] = { ["name"] = "Plainswalker Bearer", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The mammoths of the Ohn'ahran Plains are unaccustomed to carrying people, as their centaur neighbors do not typically ride mounts. They can learn to bear riders, however. Some even do so enthusiastically.\"\nWorld Event:\nCentaur Hunts (first hunt of each week)" }
entries[192792] = { ["name"] = "Bestowed Thunderspine Packleader", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"A gift from Merithra, who blessed these thunderspines to ensure that no matter where the Maruuk clans roam, they will always be under the green dragonflight's protection.\"\nAchievement:\nCentaur of Attention\nCategory:\nExploration" }
entries[192793] = { ["name"] = "PH Thunder Lizard Black", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding" }
entries[192794] = { ["name"] = "PH Thunder Lizard Blue", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding" }
entries[192795] = { ["name"] = "Rejuvenating Draught", ["text"] = "Quest Item\nUse: Invigorate an Injured Gelikyr soldier in the lower terrace of the Gelikyr Overlook.\n\"Viscous prismatic liquid fills the vial.\"" }
entries[192796] = { ["name"] = "Explorer's Stonehide Packbeast", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"A true explorer never stays in one place for long. Having a reliable packbeast with a strong back and sturdy legs is essential for travel.\"\nVendor:\nProvisioner Aristta\nZone:\nThaldraszus\nCost:\n20000" }
entries[192797] = { ["name"] = "Gral's Discarded Tooth", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+244 [Agility or Strength or Intellect]\nEquip: Your harmful spells and abilities have a high chance to summon a spirit shark that deals 4230 Frost damage split among your target and nearby enemies.\n\nDamage is increased for each enemy struck, up to 5 enemies.\nSell Price:" }
entries[192799] = { ["name"] = "Lizi's Reins", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon Lizi, Thunderspine Tramper. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Nothing will stop Lizi from her mission to eat all the world's fruit.\"\nQuest:\nTo Tame A Thunderspine\nZone:\nOhn'ahran Plains" }
entries[192800] = { ["name"] = "Skyskin Hornstrider", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The instability of primalist storms in potential timelines sometimes causes creatures to absorb the energies from the very storms. These creatures tend to be docile towards those who are able to face the fury of these chronomatic anomalies.\"\nVendor:\nBrendormi\nCost:\n150\n3000" }
entries[192801] = { ["name"] = "PH Primal Tallstrider White", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding" }
