entries[192803] = { ["name"] = "PH Primal Tallstrider Red", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding" }
entries[192804] = { ["name"] = "PH Primal Tallstrider Green", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding" }
entries[192805] = { ["name"] = "Wildlife Sample", ["text"] = "Quest Item\n\"A sample of the local wildlife from around the Titan Temple.\"" }
entries[192806] = { ["name"] = "Raging Magmammoth", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Most lava flows. This lava charges.\"\nAchievement:\nGlory of the Vault Raider\nCategory:\nDungeons & Raids" }
entries[192807] = { ["name"] = "Renewed Magmammoth", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Reforged after destruction at the hands of the Druids of the Flame, this magmammoth is ready to stomp any foes in its path.\"\nDrop:\nDreamsurges" }
entries[192808] = { ["name"] = "Primalist Orders", ["text"] = "Quest Item\n\"Scrawled across the parchment are Primalists' plans for invading Tyrhold.\"" }
entries[192809] = { ["name"] = "Temporal Residue", ["text"] = "Quest Item\nCrafting Reagent\n\"The sands of time cover those lost in the timeways.\"" }
entries[192810] = { ["name"] = "Basket of Dried Fish", ["text"] = "Quest Item\n\"A basket of fish, salted and dried for the journey.\"" }
entries[192811] = { ["name"] = "Shikaar Weaponry", ["text"] = "Quest Item\n\"Fine Shikaar spears, crafted for precision in the hunt.\"" }
entries[192812] = { ["name"] = "Feralbloom Pod", ["text"] = "Quest Item\n\"Creates a soothing paste for healing open wounds when powdered and mixed with water and honey.\"" }
entries[192833] = { ["name"] = "Misshapen Filigree", ["text"] = "Crafting Reagent\n\"Purchased from Jewelcrafting vendors across the Dragon Isles. Can be bought and sold on the auction house.\"\nSell Price:" }
entries[192872] = { ["name"] = "Fractured Glass", ["text"] = "Crafting Reagent\n\"Acquired by Jewelcrafters when prospecting ore from the Dragon Isles. Can be bought and sold on the auction house.\"\nSell Price:" }
entries[192880] = { ["name"] = "Crumbled Stone", ["text"] = "Crafting Reagent\n\"Acquired by Jewelcrafters when prospecting ore from the Dragon Isles. Can be bought and sold on the auction house.\"\nSell Price:" }
entries[192893] = { ["name"] = "Jeweled Dragon's Heart", ["text"] = "Binds when picked up\nCrafting Reagent\n\"A marvelous although fragile gemstone, it can be cracked to reveal a small hoard of gems found across the Dragon Isles.\"\n<Right Click to Open>\nSell Price:" }
entries[192996] = { ["name"] = "Pendant of Impending Perils", ["text"] = "Binds when equipped\nNeck\n+82 Stamina\n+ 136 Random Stat 1\n+ 136 Random Stat 2\nSell Price:" }
entries[192997] = { ["name"] = "Crimson Combatant's Jeweled Signet", ["text"] = "Binds when equipped\nFinger\n+182 Stamina\n+ 287 Versatility\nSell Price:" }
entries[192998] = { ["name"] = "Crimson Combatant's Jeweled Amulet", ["text"] = "Binds when equipped\nNeck\n+182 Stamina\n+ 287 Versatility\nSell Price:" }
entries[192999] = { ["name"] = "Signet of Titanic Insight", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+234 Stamina\n+ 360 Random Stat 1\n+ 360 Random Stat 2" }
entries[193000] = { ["name"] = "Ring-Bound Hourglass", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+234 Stamina\n+ 360 Random Stat 1\n+ 360 Random Stat 2\nUse: Visit a place you may have long since forgotten. (20 Hrs Cooldown)" }
entries[193001] = { ["name"] = "Elemental Lariat", ["text"] = "Binds when picked up\nNeck\n+234 Stamina\n+ 360 Random Stat 1\n+ 360 Random Stat 2\nEquip: Your spells and abilities have a chance to empower one of your socketed elemental gems, granting 313 of their associated stat. Lasts 5 sec and an additional 1 sec per elemental gem.\nSell Price:" }
entries[193002] = { ["name"] = "Choker of Shielding", ["text"] = "Binds when picked up\nNeck\n+234 Stamina\n+ 360 Random Stat 1\n+ 360 Random Stat 2\nUse: Drain the elemental energies from you and your gems, sacrificing 31 from each of their associated stats to shield you for 13907 per gem socketed for 10 sec.\n\nThese stats are returned to you when the shield is broken or expires. (3 Min Cooldown)" }
entries[193003] = { ["name"] = "Idol of the Life-Binder", ["text"] = "Binds when picked up\nUnique-Equipped: Idol of the Aspects (1)\nTrinket\n+244 [Agility or Strength or Intellect]\nEquip: Your spells and abilities have a chance to grant 34 Critical Strike per Alexstraszite you have equipped. Upon reaching 18 stacks, all stacks are consumed and you gain 573 secondary stats, split evenly for 15 sec.\n\"Tomorrow will bring you new challenges, and you must be ready to face them.\"\nSell Price:" }
entries[193004] = { ["name"] = "Idol of the Spell-Weaver", ["text"] = "Binds when picked up\nUnique-Equipped: Idol of the Aspects (1)\nTrinket\n+244 [Agility or Strength or Intellect]\nEquip: Your spells and abilities have a chance to grant 34 Versatility per Malygite you have equipped. Upon reaching 18 stacks, all stacks are consumed and you gain 573 secondary stats, split evenly for 15 sec.\n\"I have lost much in my time, mortal, too much in fact.\"\nSell Price:" }
entries[193005] = { ["name"] = "Idol of the Dreamer", ["text"] = "Binds when picked up\nUnique-Equipped: Idol of the Aspects (1)\nTrinket\n+244 [Agility or Strength or Intellect]\nEquip: Your spells and abilities have a chance to grant 34 Haste per Ysemerald you have equipped. Upon reaching 18 stacks, all stacks are consumed and you gain 573 secondary stats, split evenly for 15 sec.\n\"Whatever comes, I know you will face it with courage.\"\nSell Price:" }
entries[193006] = { ["name"] = "Idol of the Earth-Warder", ["text"] = "Binds when picked up\nUnique-Equipped: Idol of the Aspects (1)\nTrinket\n+244 [Agility or Strength or Intellect]\nEquip: Your spells and abilities have a chance to grant 34 Mastery per Neltharite you have equipped. Upon reaching 18 stacks, all stacks are consumed and you gain 573 secondary stats, split evenly for 15 sec.\n\"It is done. All have given that which must be given. I now seal the Dragon Soul forever.\"\nSell Price:" }
entries[193032] = { ["name"] = "Jeweled Offering", ["text"] = "Toy\nUse: Humbly offer your most prized possession to whomever considers you worthy enough to accept it. (1 Day Cooldown)\nSell Price:" }
entries[193033] = { ["name"] = "Convergent Prism", ["text"] = "Toy\nUse: Clutch the enchanted prism in your hand to guide a beam of light to very precise locations.\n\nThe beam is only visible to members of your party or raid. (5 Sec Cooldown)\nSell Price:" }
