entries[193451] = { ["name"] = "Slimy Expulsion Boots", ["text"] = "Binds when picked up\nFeet Leather\n235 Armor\n+193 [Agility or Intellect]\n+312 Stamina\n+ 128 Versatility\n+ 205 Mastery\nDurability 80 / 80\nEquip: These boots ooze a toxic slime which slows your actions, reducing haste by 66 . Your attacks will occasionally splash slime onto your target, dealing 2674 Nature damage.\n\nThese effects are increased by 100% if you equip an item crafted with a Toxified Armor Patch.\nSell Price:" }
