entries[194296] = { ["name"] = "Pattern: Fiddle with Draconium Fabric Cutters", ["text"] = "Binds when picked up\nUse: Teaches you how to fiddle with Draconium Fabric Cutters.\nHaving mastered your craft, perhaps fiddling with your tools will stimulate your mind? The only guarantee is their destruction!\nRequires Dragon Isles Tailoring (50)\nSell Price:\nFiddle with Draconium Fabric Cutters\n\"What would happen if pressure were applied there while pulling here?\"\nRequires Spring-Loaded Draconium Fabric Cutters , Draconium Needle Set" }
entries[194297] = { ["name"] = "Pattern: Fiddle with Khaz'gorite Fabric Cutters", ["text"] = "Binds when picked up\nUse: Teaches you how to fiddle with Khaz'gorite Fabric Cutters.\nHaving mastered your craft, perhaps fiddling with your tools will stimulate your mind? The only guarantee is their destruction!\nRequires Dragon Isles Tailoring (50)\nSell Price:\nFiddle with Khaz'gorite Fabric Cutters\n\"What would happen if pressure were applied there while pulling here?\"\nRequires Spring-Loaded Khaz'gorite Fabric Cutters , Draconium Needle Set" }
