entries[194299] = { ["name"] = "Decoration of Flame", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+351 [Agility or Strength]\nUse: Stomp the ground, commanding flames to radiate outward from your position, dealing 30948 Fire damage split between all enemies struck and granting you a 57788 shield for 30 sec. After a delay, the flames return, dealing the same damage and refreshing the shield.\n\nDamage and absorption are increased for each enemy struck, up to 5 enemies. (2 Min Cooldown)\nSell Price:" }
entries[194300] = { ["name"] = "Conjured Chillglobe", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+351 Intellect\nUse: If your mana is above 65%, toss the Chillglobe at your target, inflicting 55707 Frost damage.\n\nIf your mana is below 65%, instead drink from the Chillglobe to restore 4523 mana instantly. (1 Min Cooldown)\nSell Price:" }
entries[194301] = { ["name"] = "Whispering Incarnate Icon", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+371 [Agility or Strength or Intellect]\nEquip: Succumb to the Icon's whispers and become Infused with Frost , increasing your Critical Strike by 478 .\n\nFighting alongside allies who are Infused with Earth or Fire has a chance to grant you 131 of their Infusion's stat for 12 sec.\n\nInfusion based on your current specialization. (1.5s cooldown)\nSell Price:" }
entries[194302] = { ["name"] = "Storm-Eater's Boon", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+371 [Agility or Strength]\nUse: Accept the storm, becoming a Primal Air Elemental and immobilizing yourself for 10 sec.\n\nWhile in this form, the winds around you deal 6309 Nature damage per second to all enemies within 10 yards, intensifying by 10% each second until the transformation subsides. (3 Min Cooldown)\nSell Price:" }
entries[194303] = { ["name"] = "Rumbling Ruby", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+351 Strength\nEquip: Your attacks slowly build Concussive Force, granting 21 attack power per stack.\n\nAt 10 stacks, your next 3 melee abilities emit a shockwave in front of you, dealing 16542 bonus Nature damage to all enemies in a line. Shockwaves deal more damage to enemies at high health. (500ms cooldown)\nSell Price:" }
entries[194304] = { ["name"] = "Iceblood Deathsnare", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+351 Intellect\nUse: Deal 40232 Frost damage to your target, encasing them and nearby enemies in a Crystalline Web for 15 sec. Webbed enemies are slowed by 15% and take 3185 Frost damage when any enemy in the web is struck.\n\nDamage is increased for each webbed enemy, up to 5. Damage per target is reduced beyond 5 enemies. (2 Min Cooldown)\nSell Price:" }
entries[194305] = { ["name"] = "Controlled Current Technique", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+371 Agility\nEquip: Your critical strikes have a chance to build Static Electricity, granting 2% attack speed per stack. This effect may occur every 1 sec.\n\nAt 10 stacks lightning surges through you, increasing your movement speed by 30% for 12 seconds. While surging, your auto attacks jolt your target and 1 nearby enemy for 6470 Nature damage.\n\nWhen this effect fades, you become grounded for 1 min and unable to generate Static Electricity. (1.5s cooldown)\nSell Price:" }
entries[194306] = { ["name"] = "All-Totem of the Master", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+371 [Agility or Strength]\nEquip: Enter an Elemental Stance. Successfully dodging or parrying an attack unleashes a powerful Elemental Counterattack to enemies in front of you as you assume the next stance.\n\nThis effect can only occur once every 30 seconds. (30s cooldown)\nSell Price:" }
entries[194307] = { ["name"] = "Broodkeeper's Promise", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+382 Intellect\nUse: Designate another player to bond with, becoming their Guardian for 1 hour.\n\nWhile bonded, you and your ally gain [source value] Versatility and restore [source value] health per second. If you are within 15 yards of one another, these bonuses are increased.\n\nValid only for healer specializations. (5 Sec Cooldown)\nSell Price:", ["unresolvedValues"] = true }
entries[194308] = { ["name"] = "Manic Grieftorch", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+382 [Agility or Strength]\nUse: Channel for 2 sec, unleashing a furious volley of flame around your target, dealing [ 20285 * (8) * (1 + Versatility)] Fire damage to your target with a chance to strike nearby enemies for additional damage.\n\nWhenever an allied player dies, this cooldown is reduced by 90 seconds. (2 Min Cooldown)\nSell Price:" }
entries[194309] = { ["name"] = "Spiteful Storm", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+382 [Agility or Strength or Intellect]\nEquip: Casting spells and abilities builds stacks of Spite. At 5, a Spiteful Stormbolt arcs towards your current target, dealing [ 1828 * (6) * (1 + Versatility)] Nature damage over 3 sec.\n\nUpon expiration the bolt returns, increasing the amount of Spite needed by 1 and permanently increasing Spiteful Stormbolt's damage against them until either of you die. (1s cooldown)\nSell Price:" }
entries[194310] = { ["name"] = "Desperate Invoker's Codex", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+382 Intellect\nEquip: Casting spells grants stacks of Hatred, permanently lowering this trinket's cooldown by 1 second until combat ends. This effect stacks up to 180 times. (1s cooldown)\nUse: Let loose a dangerous current of lightning, dealing 125328 Nature damage to your target and 665 Nature damage to yourself. Self-damage increases with your stacks of Hatred. (4 Min Cooldown)\nSell Price:" }
